export const MINIAPP_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>2fauth</title>\n  <script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js\"></script>\n  <style>\n    @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&display=swap');\n\n    :root {\n      --bg: #09090b;\n      --surface: rgba(15, 15, 17, 0.82);\n      --surface-hover: #18181b;\n      --border: #27272a;\n      --border-bright: #52525b;\n      --accent: #d8b4fe;\n      --accent-glow: rgba(216, 180, 254, 0.35);\n      --success: #a7f3d0;\n      --warning: #fde047;\n      --danger: #fca5a5;\n      --text: #e2e2ec;\n      --text-bright: #ffffff;\n      --muted: #76778f;\n      --font-mono: 'JetBrains Mono', monospace;\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      font-family: var(--font-mono);\n      -webkit-tap-highlight-color: transparent;\n      scrollbar-width: thin;\n      scrollbar-color: var(--border) transparent;\n      text-transform: lowercase;\n    }\n\n    body {\n      background: var(--bg);\n      color: var(--text);\n      min-height: 100vh;\n      overflow-x: hidden;\n      position: relative;\n      padding: 16px;\n      padding-bottom: 85px;\n    }\n\n    body::before {\n      content: \"\";\n      position: fixed;\n      inset: -20px;\n      z-index: 0;\n      background-image: url(\"/bg.jpg\");\n      background-size: cover;\n      background-position: center;\n      background-repeat: no-repeat;\n      transform: translate(0, 0) scale(1);\n      animation: panBackground 15s ease-in-out infinite;\n      opacity: 0.85;\n    }\n\n    @keyframes panBackground {\n      0% {\n        transform: translate(0, 0) scale(1);\n      }\n      50% {\n        transform: translate(-10px, -10px) scale(1.05);\n      }\n      100% {\n        transform: translate(0, 0) scale(1);\n      }\n    }\n\n    body::after {\n      content: \"\";\n      position: fixed;\n      inset: 0;\n      pointer-events: none;\n      z-index: 9999;\n      background: repeating-linear-gradient(\n        0deg,\n        transparent,\n        transparent 2px,\n        rgba(0, 0, 0, 0.06) 2px,\n        rgba(0, 0, 0, 0.06) 4px\n      );\n    }\n\n    .app-container {\n      position: relative;\n      z-index: 10;\n      max-width: 640px;\n      margin: 0 auto;\n    }\n\n    header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding-bottom: 12px;\n      border-bottom: 1px solid var(--border);\n      margin-bottom: 14px;\n    }\n\n    .brand {\n      display: flex;\n      align-items: baseline;\n      gap: 8px;\n    }\n\n    .brand h1 {\n      font-size: 1.35rem;\n      font-weight: 700;\n      letter-spacing: 0.15em;\n      color: #e9d8fd;\n      text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8), 0 0 20px rgba(168, 85, 247, 0.4);\n    }\n\n    .tag {\n      font-size: 0.65rem;\n      color: var(--accent);\n      opacity: 0.85;\n      letter-spacing: 0.05em;\n    }\n\n    .clock {\n      font-size: 0.72rem;\n      color: var(--muted);\n      letter-spacing: 0.05em;\n    }\n\n    .status-bar {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      font-size: 0.72rem;\n      margin-bottom: 14px;\n      color: var(--muted);\n    }\n\n    .status-pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 3px 8px;\n      background: rgba(15, 15, 17, 0.85);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      backdrop-filter: blur(12px);\n    }\n\n    .dot {\n      width: 6px;\n      height: 6px;\n      border-radius: 50%;\n      background: var(--muted);\n    }\n\n    .dot.active {\n      background: var(--success);\n      box-shadow: 0 0 8px var(--success);\n    }\n\n    .dot.locked {\n      background: var(--danger);\n      box-shadow: 0 0 8px var(--danger);\n    }\n\n    .search-box {\n      width: 100%;\n      background: rgba(15, 15, 17, 0.82);\n      border: 1px solid var(--border);\n      color: var(--text-bright);\n      padding: 9px 12px;\n      border-radius: 4px;\n      font-size: 0.8rem;\n      outline: none;\n      margin-bottom: 14px;\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      transition: all 0.15s ease;\n      box-shadow: 0 0 12px rgba(0, 0, 0, 0.4);\n    }\n\n    .search-box:focus {\n      border-color: var(--accent);\n      box-shadow: 0 0 14px rgba(216, 180, 254, 0.2);\n    }\n\n    .search-box::placeholder {\n      color: var(--muted);\n    }\n\n    .accounts-list {\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n    }\n\n    .account-card {\n      background: rgba(15, 15, 17, 0.82);\n      border: 1px solid var(--border);\n      border-radius: 6px;\n      padding: 14px 16px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      gap: 12px;\n      cursor: pointer;\n      position: relative;\n      overflow: hidden;\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      transition: all 0.15s ease;\n      box-shadow: 0 0 14px rgba(0, 0, 0, 0.45);\n    }\n\n    .account-card:hover {\n      border-color: var(--border-bright);\n    }\n\n    .account-card:active {\n      transform: scale(0.99);\n      border-color: var(--accent);\n    }\n\n    .account-info {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n      min-width: 0;\n      flex: 1;\n      overflow: hidden;\n    }\n\n    .account-header {\n      display: flex;\n      align-items: baseline;\n      gap: 6px;\n      min-width: 0;\n      overflow: hidden;\n    }\n\n    .service-name {\n      font-size: 0.95rem;\n      font-weight: 700;\n      color: var(--text-bright);\n      white-space: nowrap;\n      flex-shrink: 0;\n    }\n\n    .account-label {\n      font-size: 0.7rem;\n      color: var(--muted);\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n      min-width: 0;\n    }\n\n    .totp-code {\n      font-size: 1.55rem;\n      font-weight: 700;\n      letter-spacing: 0.1em;\n      color: #e9d8fd;\n      text-shadow: 0 0 14px rgba(216, 180, 254, 0.35);\n      line-height: 1.1;\n      white-space: nowrap;\n    }\n\n    .account-actions {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      flex-shrink: 0;\n    }\n\n    .btn-copy {\n      background: var(--accent);\n      color: #09090b;\n      font-weight: 700;\n      font-size: 0.72rem;\n      letter-spacing: 0.06em;\n      padding: 7px 12px;\n      border-radius: 3px;\n      border: none;\n      cursor: pointer;\n      transition: all 0.15s ease;\n      user-select: none;\n      box-shadow: 0 0 10px rgba(216, 180, 254, 0.25);\n      flex-shrink: 0;\n      white-space: nowrap;\n    }\n\n    .btn-copy:hover {\n      background: #ffffff;\n    }\n\n    .btn-copy:active {\n      transform: scale(0.94);\n    }\n\n    .timer-container {\n      position: relative;\n      width: 44px;\n      height: 44px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-shrink: 0;\n    }\n\n    .timer-svg {\n      width: 44px;\n      height: 44px;\n      transform: rotate(-90deg);\n    }\n\n    .timer-circle-bg {\n      fill: none;\n      stroke: rgba(255, 255, 255, 0.08);\n      stroke-width: 3.5;\n    }\n\n    .timer-circle-progress {\n      fill: none;\n      stroke: var(--success);\n      stroke-width: 3.5;\n      stroke-linecap: round;\n      stroke-dasharray: 113;\n      stroke-dashoffset: 0;\n      transition: stroke-dashoffset 1s linear, stroke 0.3s ease;\n    }\n\n    .timer-text {\n      position: absolute;\n      font-size: 0.68rem;\n      font-weight: 700;\n      color: var(--text);\n    }\n\n    .action-bar {\n      position: fixed;\n      bottom: 0;\n      left: 0;\n      right: 0;\n      background: rgba(9, 9, 11, 0.92);\n      border-top: 1px solid var(--border);\n      padding: 12px 16px;\n      display: flex;\n      gap: 10px;\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      z-index: 100;\n    }\n\n    .btn {\n      flex: 1;\n      padding: 10px;\n      border-radius: 4px;\n      font-size: 0.78rem;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 6px;\n      border: 1px solid var(--border);\n      background: rgba(15, 15, 17, 0.85);\n      color: var(--text);\n      transition: all 0.15s ease;\n    }\n\n    .btn-primary {\n      background: var(--accent);\n      color: #09090b;\n      border-color: var(--accent);\n      box-shadow: 0 0 12px rgba(216, 180, 254, 0.3);\n    }\n\n    .btn-primary:active {\n      background: #ffffff;\n      transform: scale(0.98);\n    }\n\n    .btn-danger {\n      border-color: rgba(252, 165, 165, 0.3);\n      color: var(--danger);\n    }\n\n    .modal-backdrop {\n      position: fixed;\n      inset: 0;\n      background: rgba(0, 0, 0, 0.82);\n      backdrop-filter: blur(12px);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 16px;\n      z-index: 1000;\n      opacity: 0;\n      pointer-events: none;\n      transition: opacity 0.2s ease;\n    }\n\n    .modal-backdrop.active {\n      opacity: 1;\n      pointer-events: auto;\n    }\n\n    .modal-card {\n      background: rgba(15, 15, 17, 0.95);\n      border: 1px solid var(--border-bright);\n      border-radius: 8px;\n      padding: 22px;\n      width: 100%;\n      max-width: 360px;\n      box-shadow: 0 0 28px rgba(0, 0, 0, 0.9);\n    }\n\n    .modal-title {\n      font-size: 1rem;\n      font-weight: 700;\n      color: var(--text-bright);\n      margin-bottom: 6px;\n      letter-spacing: 0.05em;\n    }\n\n    .modal-subtitle {\n      font-size: 0.72rem;\n      color: var(--muted);\n      margin-bottom: 16px;\n      line-height: 1.4;\n    }\n\n    .modal-tabs {\n      display: flex;\n      gap: 6px;\n      background: rgba(0, 0, 0, 0.4);\n      padding: 3px;\n      border-radius: 6px;\n      border: 1px solid var(--border);\n      margin-bottom: 14px;\n    }\n\n    .modal-tab-btn {\n      flex: 1;\n      padding: 7px 10px;\n      font-size: 0.72rem;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      border: none;\n      background: transparent;\n      color: var(--muted);\n      cursor: pointer;\n      border-radius: 4px;\n      transition: all 0.15s ease;\n    }\n\n    .modal-tab-btn.active {\n      background: var(--accent);\n      color: #09090b;\n      box-shadow: 0 0 10px rgba(216, 180, 254, 0.3);\n    }\n\n    .field-label {\n      font-size: 0.68rem;\n      font-weight: 700;\n      color: var(--text);\n      margin-bottom: 4px;\n      letter-spacing: 0.04em;\n      display: block;\n    }\n\n    .drop-zone {\n      border: 2px dashed var(--border-bright);\n      border-radius: 6px;\n      padding: 24px 16px;\n      text-align: center;\n      cursor: pointer;\n      background: rgba(0, 0, 0, 0.25);\n      transition: all 0.2s ease;\n      margin-bottom: 14px;\n    }\n\n    .drop-zone:hover, .drop-zone.dragover {\n      border-color: var(--accent);\n      background: rgba(216, 180, 254, 0.05);\n      box-shadow: 0 0 16px rgba(216, 180, 254, 0.15);\n    }\n\n    .drop-icon {\n      font-size: 1.8rem;\n      margin-bottom: 6px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .lucide-icon {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      vertical-align: middle;\n      stroke: currentColor;\n    }\n\n    .anim-pulse {\n      animation: animPulse 2.2s ease-in-out infinite;\n    }\n    @keyframes animPulse {\n      0%, 100% { opacity: 0.5; transform: scale(0.96); }\n      50% { opacity: 1; transform: scale(1.04); filter: drop-shadow(0 0 8px var(--accent)); }\n    }\n\n    .anim-float {\n      animation: animFloat 3s ease-in-out infinite;\n    }\n    @keyframes animFloat {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-4px); }\n    }\n\n    .anim-bounce {\n      animation: animBounce 2s ease-in-out infinite;\n    }\n    @keyframes animBounce {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-3px); }\n    }\n\n    .scan-laser-beam {\n      animation: scanLaser 2.2s ease-in-out infinite alternate;\n      transform-origin: center;\n    }\n    @keyframes scanLaser {\n      0% { transform: translateY(-7px); opacity: 0.35; }\n      50% { opacity: 1; stroke: #ffffff; filter: drop-shadow(0 0 5px var(--accent)); }\n      100% { transform: translateY(7px); opacity: 0.35; }\n    }\n\n    .anim-spin-hover:hover {\n      animation: animSpin 0.7s cubic-bezier(0.4, 0, 0.2, 1);\n    }\n    @keyframes animSpin {\n      from { transform: rotate(0deg); }\n      to { transform: rotate(360deg); }\n    }\n\n    .anim-tilt-hover:hover {\n      animation: animTilt 0.4s ease-in-out;\n    }\n    @keyframes animTilt {\n      0%, 100% { transform: rotate(0deg); }\n      50% { transform: rotate(-12deg); }\n    }\n\n    .anim-twinkle {\n      animation: animTwinkle 2.5s ease-in-out infinite;\n    }\n    @keyframes animTwinkle {\n      0%, 100% { opacity: 0.6; transform: scale(0.9); }\n      50% { opacity: 1; transform: scale(1.15); filter: drop-shadow(0 0 4px var(--accent)); }\n    }\n\n    .anim-trash-hover:hover {\n      animation: animTrashWiggle 0.4s ease-in-out;\n    }\n    @keyframes animTrashWiggle {\n      0%, 100% { transform: rotate(0deg); }\n      25% { transform: rotate(-10deg); }\n      75% { transform: rotate(10deg); }\n    }\n\n    .anim-shackle {\n      animation: shackleSnap 3s ease-in-out infinite;\n      transform-origin: center;\n    }\n    @keyframes shackleSnap {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-2.5px); }\n    }\n\n    @keyframes shakeInput {\n      0%, 100% { transform: translateX(0); }\n      20%, 60% { transform: translateX(-8px); }\n      40%, 80% { transform: translateX(8px); }\n    }\n    .shake {\n      animation: shakeInput 0.4s ease-in-out;\n      border-color: var(--danger) !important;\n      box-shadow: 0 0 14px rgba(252, 165, 165, 0.4) !important;\n    }\n\n    .drop-title {\n      font-size: 0.78rem;\n      font-weight: 700;\n      color: var(--text-bright);\n      margin-bottom: 4px;\n    }\n\n    .drop-sub {\n      font-size: 0.68rem;\n      color: var(--muted);\n    }\n\n    .pin-input {\n      width: 100%;\n      background: rgba(0, 0, 0, 0.6);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      padding: 12px;\n      color: var(--text-bright);\n      font-size: 1.4rem;\n      text-align: center;\n      letter-spacing: 0.35em;\n      outline: none;\n      margin-bottom: 16px;\n    }\n\n    .pin-input:focus {\n      border-color: var(--accent);\n      box-shadow: 0 0 12px rgba(216, 180, 254, 0.25);\n    }\n\n    .toast {\n      position: fixed;\n      top: 24px;\n      left: 50%;\n      transform: translateX(-50%) translateY(-30px);\n      background: rgba(15, 15, 17, 0.95);\n      border: 1px solid var(--accent);\n      color: var(--accent);\n      padding: 8px 18px;\n      border-radius: 20px;\n      font-size: 0.75rem;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      opacity: 0;\n      pointer-events: none;\n      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n      z-index: 2000;\n      box-shadow: 0 4px 16px rgba(0,0,0,0.7), 0 0 14px rgba(216, 180, 254, 0.3);\n      backdrop-filter: blur(12px);\n    }\n\n    .toast.show {\n      transform: translateX(-50%) translateY(0);\n      opacity: 1;\n    }\n\n    .empty-state {\n      text-align: center;\n      padding: 32px 20px;\n      background: rgba(15, 15, 17, 0.88);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      box-shadow: 0 0 20px rgba(0, 0, 0, 0.6);\n      color: var(--text);\n      font-size: 0.85rem;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .empty-state-icon {\n      font-size: 1.8rem;\n      filter: drop-shadow(0 0 12px rgba(216, 180, 254, 0.4));\n    }\n\n    .empty-state-title {\n      font-size: 1rem;\n      font-weight: 700;\n      color: var(--text-bright);\n      letter-spacing: 0.05em;\n      text-shadow: 0 0 14px rgba(216, 180, 254, 0.25);\n    }\n\n    .empty-state-desc {\n      font-size: 0.75rem;\n      color: var(--accent);\n      line-height: 1.5;\n      max-width: 280px;\n      opacity: 0.9;\n    }\n\n    .empty-state-btn {\n      margin-top: 6px;\n      background: var(--accent);\n      color: #09090b;\n      font-weight: 700;\n      font-size: 0.78rem;\n      letter-spacing: 0.06em;\n      padding: 10px 22px;\n      border-radius: 4px;\n      border: none;\n      cursor: pointer;\n      box-shadow: 0 0 14px rgba(216, 180, 254, 0.35);\n      transition: all 0.15s ease;\n    }\n\n    .empty-state-btn:hover {\n      background: #ffffff;\n      transform: scale(1.02);\n    }\n\n    .empty-state-btn:active {\n      transform: scale(0.97);\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"app-container\">\n    <header>\n      <div class=\"brand\">\n        <h1>2fauth</h1>\n        <span class=\"tag\">[vault node]</span>\n      </div>\n      <div class=\"clock\" id=\"liveClock\">00:00:00 UTC</div>\n    </header>\n\n    <div class=\"status-bar\">\n      <div class=\"status-pill\">\n        <div class=\"dot active\" id=\"statusDot\"></div>\n        <span id=\"statusText\">connected</span>\n      </div>\n      <div class=\"status-pill\" id=\"lockStatusPill\">\n        <span id=\"lockStatusText\">locked</span>\n      </div>\n    </div>\n\n    <input type=\"text\" class=\"search-box\" id=\"searchBox\" placeholder=\"filter accounts...\" autocomplete=\"off\">\n\n    <div class=\"accounts-list\" id=\"accountsList\">\n      <div class=\"empty-state\">\n        <div class=\"empty-state-icon\">\n          <svg class=\"lucide-icon anim-pulse\" width=\"38\" height=\"38\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M4.9 19.1C1 15.2 1 8.8 4.9 4.9\"/>\n            <path d=\"M7.8 16.2c-2.3-2.3-2.3-6.1 0-8.5\"/>\n            <circle cx=\"12\" cy=\"12\" r=\"2\" fill=\"var(--accent)\"/>\n            <path d=\"M16.2 7.8c2.3 2.3 2.3 6.1 0 8.5\"/>\n            <path d=\"M19.1 4.9C23 8.8 23 15.1 19.1 19\"/>\n          </svg>\n        </div>\n        <div class=\"empty-state-title\">connecting to vault...</div>\n        <div class=\"empty-state-desc\">fetching zero-knowledge encrypted payload from edge node.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"action-bar\" id=\"actionBar\" style=\"display: none;\">\n    <button class=\"btn btn-primary\" id=\"btnAdd\">+ add account</button>\n    <button class=\"btn btn-danger\" id=\"btnLock\">lock vault</button>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"pinModal\">\n    <div class=\"modal-card\">\n      <div class=\"modal-title\">enter master pin</div>\n      <div class=\"modal-subtitle\">your pin derives the aes-256 decryption key in local browser memory.</div>\n      <input type=\"password\" class=\"pin-input\" id=\"pinInput\" maxlength=\"8\" inputmode=\"numeric\" placeholder=\"••••\" autofocus>\n      <div style=\"display: flex; gap: 8px;\">\n        <button class=\"btn\" id=\"btnCancelPin\">cancel</button>\n        <button class=\"btn btn-primary\" id=\"btnSubmitPin\">unlock</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"addModal\">\n    <div class=\"modal-card\">\n      <div class=\"modal-title\">+ add 2fa account</div>\n      <div class=\"modal-tabs\">\n        <button class=\"modal-tab-btn active\" id=\"tabBtnManual\" type=\"button\">manual key</button>\n        <button class=\"modal-tab-btn\" id=\"tabBtnQr\" type=\"button\">scan / qr image</button>\n      </div>\n\n      <div id=\"addManualView\">\n        <label class=\"field-label\" for=\"addUriInput\">2fa secret key or link</label>\n        <input type=\"text\" class=\"search-box\" id=\"addUriInput\" placeholder=\"paste secret (e.g. JBSWY3D...) or URI\" style=\"margin-bottom: 10px;\" autocomplete=\"off\">\n\n        <label class=\"field-label\" for=\"addServiceInput\">service name</label>\n        <input type=\"text\" class=\"search-box\" id=\"addServiceInput\" placeholder=\"e.g. Google, GitHub, Binance\" style=\"margin-bottom: 10px;\" autocomplete=\"off\">\n\n        <label class=\"field-label\" for=\"addLabelInput\">account / email (optional)</label>\n        <input type=\"text\" class=\"search-box\" id=\"addLabelInput\" placeholder=\"e.g. user@gmail.com\" style=\"margin-bottom: 16px;\" autocomplete=\"off\">\n\n        <div id=\"addCollisionPrompt\" style=\"display: none; background: rgba(253, 224, 71, 0.08); border: 1px solid var(--warning); border-radius: 6px; padding: 12px; margin-bottom: 14px;\">\n          <div style=\"font-size: 0.78rem; font-weight: 700; color: var(--warning); margin-bottom: 4px; display: flex; align-items: center; gap: 6px;\">\n            <svg class=\"lucide-icon anim-bounce\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--warning)\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3\"/>\n              <path d=\"M12 9v4\"/><path d=\"M12 17h.01\"/>\n            </svg>\n            <span>account already exists</span>\n          </div>\n          <div style=\"font-size: 0.7rem; color: var(--text); margin-bottom: 10px; line-height: 1.4;\" id=\"collisionMsgText\">\n            an account for this service is already in your vault. do you want to replace its 2fa key, or add a label to keep both?\n          </div>\n          <div style=\"display: flex; gap: 8px;\">\n            <button class=\"btn btn-primary\" id=\"btnConfirmReplace\" type=\"button\" style=\"font-size: 0.7rem; padding: 6px 10px; display: inline-flex; align-items: center; gap: 5px;\">\n              <svg class=\"lucide-icon anim-spin-hover\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8\"/>\n                <path d=\"M3 3v5h5\"/>\n                <path d=\"M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16\"/>\n                <path d=\"M16 16h5v5\"/>\n              </svg>\n              <span>replace key</span>\n            </button>\n            <button class=\"btn\" id=\"btnAddLabelFocus\" type=\"button\" style=\"font-size: 0.7rem; padding: 6px 10px; display: inline-flex; align-items: center; gap: 5px;\">\n              <svg class=\"lucide-icon anim-tilt-hover\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"M12.586 2.586A2 2 0 0 0 11.172 2H4a2 2 0 0 0-2 2v7.172a2 2 0 0 0 .586 1.414l8.704 8.704a2.426 2.426 0 0 0 3.42 0l6.58-6.58a2.426 2.426 0 0 0 0-3.42z\"/>\n                <circle cx=\"7.5\" cy=\"7.5\" r=\".5\" fill=\"currentColor\"/>\n              </svg>\n              <span>add label</span>\n            </button>\n          </div>\n        </div>\n\n        <div style=\"display: flex; gap: 8px;\" id=\"addFormActions\">\n          <button class=\"btn\" id=\"btnCancelAdd\">cancel</button>\n          <button class=\"btn btn-primary\" id=\"btnSubmitAdd\">save to vault</button>\n        </div>\n\n        <div style=\"font-size: 0.68rem; color: var(--muted); margin-top: 14px; text-align: center; line-height: 1.4; display: flex; align-items: center; justify-content: center; gap: 5px;\">\n          <svg class=\"lucide-icon anim-twinkle\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .963 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.963 0z\"/>\n          </svg>\n          <span>tip: you can also send a qr screenshot directly to the bot in telegram chat!</span>\n        </div>\n      </div>\n\n      <div id=\"addQrView\" style=\"display: none;\">\n        <button class=\"btn btn-primary\" id=\"btnScanCamera\" type=\"button\" style=\"margin-bottom: 12px; width: 100%; display: none; align-items: center; justify-content: center; gap: 6px;\">\n          <svg class=\"lucide-icon\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z\"/>\n            <circle cx=\"12\" cy=\"13\" r=\"3\"/>\n          </svg>\n          <span>scan with camera</span>\n        </button>\n\n        <div class=\"drop-zone\" id=\"qrDropZone\">\n          <div class=\"drop-icon\">\n            <svg class=\"lucide-icon\" width=\"38\" height=\"38\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M3 7V5a2 2 0 0 1 2-2h2\"/>\n              <path d=\"M17 3h2a2 2 0 0 1 2 2v2\"/>\n              <path d=\"M21 17v2a2 2 0 0 1-2 2h-2\"/>\n              <path d=\"M7 21H5a2 2 0 0 1-2-2v-2\"/>\n              <rect x=\"7\" y=\"7\" width=\"3\" height=\"3\" fill=\"var(--accent)\"/>\n              <rect x=\"14\" y=\"7\" width=\"3\" height=\"3\" fill=\"var(--accent)\"/>\n              <rect x=\"7\" y=\"14\" width=\"3\" height=\"3\" fill=\"var(--accent)\"/>\n              <line class=\"scan-laser-beam\" x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\" stroke=\"var(--accent)\" stroke-width=\"2\"/>\n            </svg>\n          </div>\n          <div class=\"drop-title\">drag & drop qr screenshot</div>\n          <div class=\"drop-sub\">or click to browse from device</div>\n          <input type=\"file\" id=\"qrFileInput\" accept=\"image/*\" style=\"display: none;\">\n        </div>\n\n        <div style=\"display: flex; gap: 8px;\">\n          <button class=\"btn\" id=\"btnCancelAddQr\">cancel</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"manageModal\">\n    <div class=\"modal-card\">\n      <div class=\"modal-title\" id=\"manageServiceName\">account details</div>\n      <div class=\"modal-subtitle\" id=\"manageAccountLabel\" style=\"word-break: break-all; margin-bottom: 14px;\"></div>\n\n      <div style=\"background: rgba(0, 0, 0, 0.4); border: 1px solid var(--border); border-radius: 6px; padding: 14px; margin-bottom: 16px; text-align: center;\">\n        <div style=\"font-size: 0.68rem; color: var(--muted); margin-bottom: 6px;\">current 2fa code</div>\n        <div style=\"font-size: 1.8rem; font-weight: 700; color: #e9d8fd; letter-spacing: 0.15em; text-shadow: 0 0 16px rgba(216, 180, 254, 0.4);\" id=\"manageCodeDisplay\">--- ---</div>\n      </div>\n\n      <div id=\"deleteConfirmBox\" style=\"display: none; background: rgba(252, 165, 165, 0.08); border: 1px solid var(--danger); border-radius: 6px; padding: 14px; margin-bottom: 14px; text-align: center;\">\n        <div style=\"font-size: 0.82rem; font-weight: 700; color: var(--danger); margin-bottom: 6px; display: flex; align-items: center; justify-content: center; gap: 6px;\">\n          <svg class=\"lucide-icon anim-bounce\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--danger)\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3\"/>\n            <path d=\"M12 9v4\"/><path d=\"M12 17h.01\"/>\n          </svg>\n          <span>are you sure?</span>\n        </div>\n        <div style=\"font-size: 0.72rem; color: var(--text); margin-bottom: 12px; line-height: 1.4;\">\n          this will permanently remove this 2fa account from your vault.\n        </div>\n        <div style=\"display: flex; gap: 8px;\">\n          <button class=\"btn\" id=\"btnCancelDeleteAction\" type=\"button\">cancel</button>\n          <button class=\"btn btn-danger\" id=\"btnConfirmDeleteAction\" type=\"button\" style=\"background: rgba(252, 165, 165, 0.2); display: flex; align-items: center; justify-content: center; gap: 6px;\">\n            <svg class=\"lucide-icon anim-trash-hover\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M3 6h18\"/>\n              <path d=\"M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6\"/>\n              <path d=\"M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2\"/>\n              <line x1=\"10\" y1=\"11\" x2=\"10\" y2=\"17\"/>\n              <line x1=\"14\" y1=\"11\" x2=\"14\" y2=\"17\"/>\n            </svg>\n            <span>delete</span>\n          </button>\n        </div>\n      </div>\n\n      <div style=\"display: flex; gap: 8px;\" id=\"manageDefaultActions\">\n        <button class=\"btn\" id=\"btnCloseManage\" type=\"button\">close</button>\n        <button class=\"btn btn-danger\" id=\"btnOpenDeletePrompt\" type=\"button\" style=\"display: flex; align-items: center; justify-content: center; gap: 6px;\">\n          <svg class=\"lucide-icon anim-trash-hover\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M3 6h18\"/>\n            <path d=\"M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6\"/>\n            <path d=\"M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2\"/>\n            <line x1=\"10\" y1=\"11\" x2=\"10\" y2=\"17\"/>\n            <line x1=\"14\" y1=\"11\" x2=\"14\" y2=\"17\"/>\n          </svg>\n          <span>delete</span>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"toast\" id=\"toastMsg\">copied to clipboard</div>\n\n  <script>\n    let tg = window.Telegram?.WebApp;\n    if (tg) {\n      tg.ready();\n      tg.expand();\n      tg.headerColor = '#09090b';\n      tg.backgroundColor = '#09090b';\n    }\n\n    let state = {\n      user: null,\n      accounts: [],\n      masterKey: null,\n      salt: null,\n      pinVerifier: null,\n      decryptedAccounts: [],\n      filter: '',\n      timeOffset: 0,\n      selectedAccountId: null,\n    };\n\n    function updateClock() {\n      const now = new Date(Date.now() + (state.timeOffset || 0) * 1000);\n      const utc = now.toISOString().substring(11, 19) + ' UTC';\n      document.getElementById('liveClock').textContent = utc;\n    }\n    setInterval(updateClock, 1000);\n    updateClock();\n\n    function showToast(text) {\n      const toast = document.getElementById('toastMsg');\n      toast.textContent = text;\n      toast.classList.add('show');\n      setTimeout(() => toast.classList.remove('show'), 1500);\n    }\n\n    window.copyCode = function(code, btnId) {\n      if (navigator.clipboard && window.isSecureContext) {\n        navigator.clipboard.writeText(code).then(() => {\n          onCopySuccess(code, btnId);\n        }).catch(() => {\n          legacyCopy(code, btnId);\n        });\n      } else {\n        legacyCopy(code, btnId);\n      }\n    };\n\n    function legacyCopy(code, btnId) {\n      const el = document.createElement('textarea');\n      el.value = code;\n      el.setAttribute('readonly', '');\n      el.style.position = 'fixed';\n      el.style.left = '-9999px';\n      document.body.appendChild(el);\n      el.select();\n      try {\n        document.execCommand('copy');\n        onCopySuccess(code, btnId);\n      } catch (err) {\n        showToast('Copy failed');\n      }\n      document.body.removeChild(el);\n    }\n\n    function onCopySuccess(code, btnId) {\n      if (tg?.HapticFeedback) {\n        tg.HapticFeedback.notificationOccurred('success');\n      }\n      showToast(`copied: ${code}`);\n\n      if (btnId) {\n        const btn = document.getElementById(btnId);\n        if (btn) {\n          const prev = btn.textContent;\n          btn.textContent = 'copied!';\n          btn.style.background = 'var(--success)';\n          setTimeout(() => {\n            btn.textContent = prev;\n            btn.style.background = 'var(--accent)';\n          }, 1200);\n        }\n      }\n    }\n\n    const RFC4648_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';\n    function base32Decode(str) {\n      const clean = str.toUpperCase().replace(/[=\\s]/g, '');\n      let bits = '';\n      for (let i = 0; i < clean.length; i++) {\n        const val = RFC4648_ALPHABET.indexOf(clean[i]);\n        if (val === -1) continue;\n        bits += val.toString(2).padStart(5, '0');\n      }\n      const bytes = new Uint8Array(Math.floor(bits.length / 8));\n      for (let i = 0; i < bytes.length; i++) {\n        bytes[i] = parseInt(bits.substring(i * 8, (i + 1) * 8), 2);\n      }\n      return bytes;\n    }\n\n    async function computeTOTP(secretKey, epochSeconds = null, timeStep = 30) {\n      if (epochSeconds === null) {\n        epochSeconds = Math.floor(Date.now() / 1000) + (state.timeOffset || 0);\n      }\n      const counter = Math.floor(epochSeconds / timeStep);\n      const remainingSeconds = timeStep - (epochSeconds % timeStep);\n\n      const counterBuffer = new ArrayBuffer(8);\n      const counterView = new DataView(counterBuffer);\n      counterView.setUint32(0, Math.floor(counter / 0x100000000), false);\n      counterView.setUint32(4, counter >>> 0, false);\n\n      const secretBytes = base32Decode(secretKey);\n      const cryptoKey = await crypto.subtle.importKey(\n        'raw',\n        secretBytes,\n        { name: 'HMAC', hash: 'SHA-1' },\n        false,\n        ['sign']\n      );\n\n      const signature = await crypto.subtle.sign('HMAC', cryptoKey, counterBuffer);\n      const hmacResult = new Uint8Array(signature);\n\n      const offset = hmacResult[hmacResult.length - 1] & 0x0f;\n      const binary =\n        ((hmacResult[offset] & 0x7f) << 24) |\n        ((hmacResult[offset + 1] & 0xff) << 16) |\n        ((hmacResult[offset + 2] & 0xff) << 8) |\n        (hmacResult[offset + 3] & 0xff);\n\n      const otp = (binary % 1000000).toString().padStart(6, '0');\n      return { code: otp, remainingSeconds };\n    }\n\n    async function deriveMasterKey(pin, salt) {\n      const pinBytes = new TextEncoder().encode(pin);\n      const baseKey = await crypto.subtle.importKey('raw', pinBytes, 'PBKDF2', false, ['deriveKey']);\n      return crypto.subtle.deriveKey(\n        { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },\n        baseKey,\n        { name: 'AES-GCM', length: 256 },\n        true,\n        ['encrypt', 'decrypt']\n      );\n    }\n\n    async function verifyPin(pin, salt, targetVerifier) {\n      const data = new TextEncoder().encode(pin + ',' + Array.from(salt).join('.'));\n      const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', data));\n      if (digest.length !== targetVerifier.length) return false;\n      for (let i = 0; i < digest.length; i++) {\n        if (digest[i] !== targetVerifier[i]) return false;\n      }\n      return true;\n    }\n\n    async function decryptSecret(ciphertext, key, iv) {\n      const decrypted = await crypto.subtle.decrypt(\n        { name: 'AES-GCM', iv },\n        key,\n        ciphertext\n      );\n      return new TextDecoder().decode(decrypted);\n    }\n\n    async function encryptSecret(plaintext, key) {\n      const iv = crypto.getRandomValues(new Uint8Array(12));\n      const encrypted = await crypto.subtle.encrypt(\n        { name: 'AES-GCM', iv },\n        key,\n        new TextEncoder().encode(plaintext)\n      );\n      return { ciphertext: new Uint8Array(encrypted), iv };\n    }\n\n    async function restoreKeyFromBytes(rawBytes) {\n      state.masterKey = await crypto.subtle.importKey(\n        'raw',\n        rawBytes,\n        { name: 'AES-GCM' },\n        true,\n        ['encrypt', 'decrypt']\n      );\n\n      state.decryptedAccounts = [];\n      for (const acc of state.accounts) {\n        try {\n          const secret = await decryptSecret(\n            new Uint8Array(acc.encrypted_secret),\n            state.masterKey,\n            new Uint8Array(acc.iv)\n          );\n          state.decryptedAccounts.push({\n            id: acc.id,\n            serviceName: acc.service_name,\n            accountLabel: acc.account_label,\n            secret,\n          });\n        } catch (_) {}\n      }\n\n      document.getElementById('lockStatusText').textContent = 'unlocked';\n      document.getElementById('lockStatusPill').style.borderColor = 'var(--success)';\n      document.getElementById('actionBar').style.display = 'flex';\n      renderAccounts();\n      return true;\n    }\n\n    async function syncVault() {\n      try {\n        localStorage.removeItem('2fauth_session');\n        sessionStorage.removeItem('2fauth_pin');\n\n        const initData = tg?.initData || '';\n        const res = await fetch('/api/miniapp/sync', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ initData }),\n        });\n\n        if (!res.ok) {\n          throw new Error('Failed to load vault');\n        }\n\n        const data = await res.json();\n        if (typeof data.server_time === 'number') {\n          state.timeOffset = data.server_time - Math.floor(Date.now() / 1000);\n        }\n        state.salt = new Uint8Array(data.user.salt);\n        state.pinVerifier = new Uint8Array(data.user.pin_verifier);\n        state.accounts = data.accounts || [];\n\n        if (state.masterKey) {\n          state.decryptedAccounts = [];\n          for (const acc of state.accounts) {\n            try {\n              const secret = await decryptSecret(\n                new Uint8Array(acc.encrypted_secret),\n                state.masterKey,\n                new Uint8Array(acc.iv)\n              );\n              state.decryptedAccounts.push({\n                id: acc.id,\n                serviceName: acc.service_name,\n                accountLabel: acc.account_label,\n                secret,\n              });\n            } catch (_) {}\n          }\n        }\n\n        document.getElementById('statusText').textContent = 'synced';\n        renderAccounts();\n      } catch (err) {\n        document.getElementById('accountsList').innerHTML =\n          `<div class=\"empty-state\">\n            <div class=\"empty-state-icon\">\n              <svg class=\"lucide-icon anim-bounce\" width=\"38\" height=\"38\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--danger)\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3\"/>\n                <path d=\"M12 9v4\"/><path d=\"M12 17h.01\"/>\n              </svg>\n            </div>\n            <div class=\"empty-state-title\" style=\"color: var(--danger)\">connection error</div>\n            <div class=\"empty-state-desc\">${err.message}</div>\n          </div>`;\n      }\n    }\n\n    async function unlockWithPin(pin) {\n      const isValid = await verifyPin(pin, state.salt, state.pinVerifier);\n      if (!isValid) {\n        showToast('Incorrect PIN');\n        return false;\n      }\n\n      state.masterKey = await deriveMasterKey(pin, state.salt);\n      const rawKey = await crypto.subtle.exportKey('raw', state.masterKey);\n      const rawBytes = new Uint8Array(rawKey);\n\n      await restoreKeyFromBytes(rawBytes);\n      showToast('Vault Unlocked');\n      return true;\n    }\n\n    function lockVault() {\n      closeManageModal();\n      state.masterKey = null;\n      state.decryptedAccounts = [];\n      localStorage.removeItem('2fauth_session');\n      sessionStorage.removeItem('2fauth_pin');\n\n      document.getElementById('lockStatusText').textContent = 'locked';\n      document.getElementById('lockStatusPill').style.borderColor = 'var(--border)';\n      document.getElementById('actionBar').style.display = 'none';\n      showToast('Vault Locked');\n      renderAccounts();\n    }\n\n    async function renderAccounts() {\n      const container = document.getElementById('accountsList');\n      const query = (state.filter || '').trim().toLowerCase();\n\n      if (!state.masterKey) {\n        container.innerHTML = `\n          <div class=\"empty-state\">\n            <div class=\"empty-state-icon\">\n              <svg class=\"lucide-icon anim-pulse\" width=\"44\" height=\"44\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"1.85\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"M10 20H4a2 2 0 0 1-2-2V5c0-1.1.9-2 2-2h3.93a2 2 0 0 1 1.66.9l.82 1.2a2 2 0 0 0 1.66.9H20a2 2 0 0 1 2 2v2.5\"/>\n                <rect width=\"8\" height=\"5\" x=\"14\" y=\"17\" rx=\"1\" fill=\"rgba(216, 180, 254, 0.15)\"/>\n                <path class=\"anim-shackle\" d=\"M20 17v-2a2 2 0 1 0-4 0v2\"/>\n              </svg>\n            </div>\n            <div class=\"empty-state-title\">vault is locked</div>\n            <div class=\"empty-state-desc\">enter your master pin to derive the local aes-256 decryption key.</div>\n            <button class=\"empty-state-btn\" onclick=\"openPinModal()\">unlock vault</button>\n          </div>`;\n        return;\n      }\n\n      const filtered = state.decryptedAccounts.filter(a =>\n        a.serviceName.toLowerCase().includes(query) ||\n        (a.accountLabel && a.accountLabel.toLowerCase().includes(query))\n      );\n\n      if (filtered.length === 0) {\n        container.innerHTML = `\n          <div class=\"empty-state\">\n            <div class=\"empty-state-icon\">\n              <svg class=\"lucide-icon anim-float\" width=\"38\" height=\"38\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"m6 14 1.5-2.9A2 2 0 0 1 9.24 10H20a2 2 0 0 1 1.94 2.5l-1.54 6a2 2 0 0 1-1.95 1.5H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.69.9l.81 1.2a2 2 0 0 0 1.67.9H18a2 2 0 0 1 2 2v2\"/>\n              </svg>\n            </div>\n            <div class=\"empty-state-title\">no accounts found</div>\n            <div class=\"empty-state-desc\">add your first 2fa service using the [+ add] button below.</div>\n          </div>`;\n        return;\n      }\n\n      const existingCards = container.querySelectorAll('.account-card');\n      const currentIds = Array.from(existingCards).map(c => c.getAttribute('data-id'));\n      const newIds = filtered.map(a => String(a.id));\n      const needsRebuild = currentIds.length !== newIds.length || !currentIds.every((id, idx) => id === newIds[idx]);\n\n      if (needsRebuild) {\n        let html = '';\n        for (const acc of filtered) {\n          const btnId = `copy_btn_${acc.id}`;\n          html += `\n            <div class=\"account-card\" id=\"card_${acc.id}\" data-id=\"${acc.id}\">\n              <div class=\"account-info\">\n                <div class=\"account-header\">\n                  <span class=\"service-name\">${acc.serviceName}</span>\n                  ${acc.accountLabel ? `<span class=\"account-label\">(${acc.accountLabel})</span>` : ''}\n                </div>\n                <div class=\"totp-code\" id=\"code_${acc.id}\">--- ---</div>\n              </div>\n              <div class=\"account-actions\">\n                <div class=\"timer-container\">\n                  <svg class=\"timer-svg\" viewBox=\"0 0 44 44\">\n                    <circle class=\"timer-circle-bg\" cx=\"22\" cy=\"22\" r=\"18\"></circle>\n                    <circle class=\"timer-circle-progress\" id=\"ring_${acc.id}\" cx=\"22\" cy=\"22\" r=\"18\"\n                            style=\"stroke-dashoffset: 0; stroke: var(--success);\"></circle>\n                  </svg>\n                  <span class=\"timer-text\" id=\"time_${acc.id}\" style=\"color: var(--success);\">30s</span>\n                </div>\n                <button class=\"btn-copy\" id=\"${btnId}\">copy</button>\n              </div>\n            </div>\n          `;\n        }\n        container.innerHTML = html;\n\n        for (const acc of filtered) {\n          const card = document.getElementById(`card_${acc.id}`);\n          const btn = document.getElementById(`copy_btn_${acc.id}`);\n\n          const doCopy = (e) => {\n            e.stopPropagation();\n            const currentCode = btn.getAttribute('data-raw-code');\n            if (currentCode) {\n              copyCode(currentCode, btn.id);\n            }\n          };\n\n          btn.addEventListener('click', doCopy);\n          card.addEventListener('click', (e) => {\n            if (e.target !== btn && !btn.contains(e.target)) {\n              openManageModal(acc);\n            }\n          });\n        }\n      }\n\n      for (const acc of filtered) {\n        const { code, remainingSeconds } = await computeTOTP(acc.secret);\n        const dashOffset = 113 - (113 * (remainingSeconds / 30));\n\n        let color = 'var(--success)';\n        if (remainingSeconds <= 5) color = 'var(--danger)';\n        else if (remainingSeconds <= 12) color = 'var(--warning)';\n\n        const formattedCode = code.slice(0, 3) + ' ' + code.slice(3);\n\n        const codeEl = document.getElementById(`code_${acc.id}`);\n        const ringEl = document.getElementById(`ring_${acc.id}`);\n        const timeEl = document.getElementById(`time_${acc.id}`);\n        const btn = document.getElementById(`copy_btn_${acc.id}`);\n\n        if (codeEl && codeEl.textContent !== formattedCode) {\n          codeEl.textContent = formattedCode;\n        }\n        if (ringEl) {\n          ringEl.style.strokeDashoffset = dashOffset;\n          ringEl.style.stroke = color;\n        }\n        if (timeEl) {\n          timeEl.textContent = remainingSeconds + 's';\n          timeEl.style.color = color;\n        }\n        if (btn) {\n          btn.setAttribute('data-raw-code', code);\n        }\n      }\n\n      if (state.selectedAccountId) {\n        const selAcc = state.decryptedAccounts.find(a => a.id === state.selectedAccountId);\n        if (selAcc) {\n          const { code } = await computeTOTP(selAcc.secret);\n          const formatted = code.slice(0, 3) + ' ' + code.slice(3);\n          const displayEl = document.getElementById('manageCodeDisplay');\n          if (displayEl && displayEl.textContent !== formatted) {\n            displayEl.textContent = formatted;\n            displayEl.setAttribute('data-raw-code', code);\n          }\n        }\n      }\n    }\n\n    setInterval(() => {\n      if (state.masterKey) {\n        renderAccounts();\n      }\n    }, 1000);\n\n    window.openPinModal = function() {\n      document.getElementById('pinModal').classList.add('active');\n      document.getElementById('pinInput').value = '';\n      document.getElementById('pinInput').focus();\n    };\n\n    document.getElementById('pinInput').addEventListener('keydown', (e) => {\n      if (e.key === 'Enter') {\n        document.getElementById('btnSubmitPin').click();\n      }\n    });\n\n    document.getElementById('searchBox').addEventListener('input', (e) => {\n      state.filter = e.target.value;\n      renderAccounts();\n    });\n\n    document.getElementById('btnCancelPin').addEventListener('click', () => {\n      document.getElementById('pinModal').classList.remove('active');\n    });\n\n    document.getElementById('btnSubmitPin').addEventListener('click', async () => {\n      const pinInput = document.getElementById('pinInput');\n      const pin = pinInput.value.trim();\n      if (!pin) return;\n      const ok = await unlockWithPin(pin);\n      if (ok) {\n        document.getElementById('pinModal').classList.remove('active');\n        pinInput.value = '';\n      } else {\n        pinInput.value = '';\n        pinInput.focus();\n        pinInput.classList.remove('shake');\n        void pinInput.offsetWidth;\n        pinInput.classList.add('shake');\n        setTimeout(() => pinInput.classList.remove('shake'), 450);\n      }\n    });\n\n    document.getElementById('btnLock').addEventListener('click', lockVault);\n    document.getElementById('btnLock').style.display = 'none';\n\n    function openManageModal(acc) {\n      state.selectedAccountId = acc.id;\n      document.getElementById('manageServiceName').textContent = acc.serviceName;\n      document.getElementById('manageAccountLabel').textContent = acc.accountLabel ? `account: ${acc.accountLabel}` : 'no account label';\n      \n      const codeEl = document.getElementById(`code_${acc.id}`);\n      const rawCode = document.getElementById(`copy_btn_${acc.id}`)?.getAttribute('data-raw-code') || '';\n      const displayEl = document.getElementById('manageCodeDisplay');\n      displayEl.textContent = codeEl ? codeEl.textContent : '--- ---';\n      displayEl.setAttribute('data-raw-code', rawCode);\n\n      document.getElementById('deleteConfirmBox').style.display = 'none';\n      document.getElementById('manageDefaultActions').style.display = 'flex';\n      document.getElementById('manageModal').classList.add('active');\n    }\n\n    function closeManageModal() {\n      state.selectedAccountId = null;\n      document.getElementById('manageModal').classList.remove('active');\n      document.getElementById('deleteConfirmBox').style.display = 'none';\n      document.getElementById('manageDefaultActions').style.display = 'flex';\n    }\n\n    document.getElementById('btnCloseManage').addEventListener('click', closeManageModal);\n\n    document.getElementById('manageCodeDisplay').addEventListener('click', () => {\n      const code = document.getElementById('manageCodeDisplay').getAttribute('data-raw-code');\n      if (code) {\n        copyCode(code, null);\n      }\n    });\n\n    document.getElementById('btnOpenDeletePrompt').addEventListener('click', () => {\n      document.getElementById('deleteConfirmBox').style.display = 'block';\n      document.getElementById('manageDefaultActions').style.display = 'none';\n    });\n\n    document.getElementById('btnCancelDeleteAction').addEventListener('click', () => {\n      document.getElementById('deleteConfirmBox').style.display = 'none';\n      document.getElementById('manageDefaultActions').style.display = 'flex';\n    });\n\n    document.getElementById('btnConfirmDeleteAction').addEventListener('click', async () => {\n      if (!state.selectedAccountId) return;\n      const accountId = state.selectedAccountId;\n      const initData = tg?.initData || '';\n\n      try {\n        const res = await fetch('/api/miniapp/delete', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ initData, accountId }),\n        });\n\n        if (res.ok) {\n          showToast('Account deleted');\n          closeManageModal();\n          state.decryptedAccounts = state.decryptedAccounts.filter(a => a.id !== accountId);\n          state.accounts = state.accounts.filter(a => a.id !== accountId);\n          renderAccounts();\n          await syncVault();\n        } else {\n          const errData = await res.json().catch(() => ({}));\n          showToast(errData.error || 'Delete failed');\n        }\n      } catch (err) {\n        showToast('Error deleting account');\n      }\n    });\n\n    function switchToAddTab(tab) {\n      const isManual = tab === 'manual';\n      document.getElementById('tabBtnManual').classList.toggle('active', isManual);\n      document.getElementById('tabBtnQr').classList.toggle('active', !isManual);\n      document.getElementById('addManualView').style.display = isManual ? 'block' : 'none';\n      document.getElementById('addQrView').style.display = isManual ? 'none' : 'block';\n    }\n\n    document.getElementById('tabBtnManual').addEventListener('click', () => switchToAddTab('manual'));\n    document.getElementById('tabBtnQr').addEventListener('click', () => switchToAddTab('qr'));\n    document.getElementById('btnCancelAddQr').addEventListener('click', () => {\n      document.getElementById('addModal').classList.remove('active');\n    });\n\n    function applyDecodedUri(raw) {\n      if (!raw) return;\n      let clean = raw.trim();\n      let secret = clean;\n      let service = '';\n      let label = '';\n\n      if (clean.startsWith('otpauth://')) {\n        try {\n          const url = new URL(clean);\n          secret = url.searchParams.get('secret') || secret;\n          service = url.searchParams.get('issuer') || '';\n          if (url.pathname) {\n            const pathPart = decodeURIComponent(url.pathname.replace(/^\\/+/, ''));\n            if (pathPart.includes(':')) {\n              const parts = pathPart.split(':');\n              if (!service) service = parts[0].trim();\n              label = parts.slice(1).join(':').trim();\n            } else if (!service) {\n              if (pathPart.includes('@')) {\n                const atParts = pathPart.split('@');\n                label = atParts[0].trim();\n                service = atParts[1].trim();\n              } else {\n                service = pathPart.trim();\n              }\n            } else {\n              label = pathPart.trim();\n            }\n          }\n        } catch (_) {}\n      }\n\n      document.getElementById('addUriInput').value = secret;\n      if (service) document.getElementById('addServiceInput').value = service;\n      if (label) document.getElementById('addLabelInput').value = label;\n    }\n\n    document.getElementById('addUriInput').addEventListener('input', (e) => {\n      const val = e.target.value.trim();\n      if (val.startsWith('otpauth://')) {\n        applyDecodedUri(val);\n      }\n    });\n\n    const btnScanCam = document.getElementById('btnScanCamera');\n    if (tg?.showScanQrPopup) {\n      btnScanCam.style.display = 'flex';\n      btnScanCam.addEventListener('click', () => {\n        tg.showScanQrPopup({ text: 'Scan 2FA QR Code' }, (data) => {\n          if (data) {\n            applyDecodedUri(data);\n            try { tg.closeScanQrPopup(); } catch (_) {}\n            showToast('QR Code Scanned');\n            switchToAddTab('manual');\n            return true;\n          }\n        });\n      });\n    }\n\n    function processQrImageFile(file) {\n      if (!file || !file.type.startsWith('image/')) {\n        showToast('Please select an image file');\n        return;\n      }\n      showToast('Scanning image...');\n      const reader = new FileReader();\n      reader.onload = (e) => {\n        const img = new Image();\n        img.onload = () => {\n          try {\n            const canvas = document.createElement('canvas');\n            canvas.width = img.width;\n            canvas.height = img.height;\n            const ctx = canvas.getContext('2d');\n            ctx.drawImage(img, 0, 0);\n            const imgData = ctx.getImageData(0, 0, img.width, img.height);\n            if (typeof window.jsQR === 'function') {\n              const code = window.jsQR(imgData.data, imgData.width, imgData.height);\n              if (code && code.data) {\n                applyDecodedUri(code.data);\n                showToast('QR Code Detected');\n                switchToAddTab('manual');\n              } else {\n                showToast('No QR code found in image');\n              }\n            } else {\n              showToast('QR decoder loading...');\n            }\n          } catch (err) {\n            showToast('Error reading image');\n          }\n        };\n        img.src = e.target.result;\n      };\n      reader.readAsDataURL(file);\n    }\n\n    const dropZone = document.getElementById('qrDropZone');\n    const fileInput = document.getElementById('qrFileInput');\n\n    dropZone.addEventListener('click', () => fileInput.click());\n    fileInput.addEventListener('change', (e) => {\n      if (e.target.files && e.target.files[0]) {\n        processQrImageFile(e.target.files[0]);\n        fileInput.value = '';\n      }\n    });\n\n    dropZone.addEventListener('dragover', (e) => {\n      e.preventDefault();\n      dropZone.classList.add('dragover');\n    });\n\n    dropZone.addEventListener('dragleave', () => {\n      dropZone.classList.remove('dragover');\n    });\n\n    dropZone.addEventListener('drop', (e) => {\n      e.preventDefault();\n      dropZone.classList.remove('dragover');\n      if (e.dataTransfer.files && e.dataTransfer.files[0]) {\n        processQrImageFile(e.dataTransfer.files[0]);\n      }\n    });\n\n    function hideCollisionPrompt() {\n      const prompt = document.getElementById('addCollisionPrompt');\n      if (prompt) prompt.style.display = 'none';\n      const actions = document.getElementById('addFormActions');\n      if (actions) actions.style.display = 'flex';\n    }\n\n    document.getElementById('addServiceInput').addEventListener('input', hideCollisionPrompt);\n    document.getElementById('addLabelInput').addEventListener('input', hideCollisionPrompt);\n\n    document.getElementById('btnAddLabelFocus').addEventListener('click', () => {\n      hideCollisionPrompt();\n      const labelInput = document.getElementById('addLabelInput');\n      labelInput.focus();\n      labelInput.placeholder = 'e.g. personal, work, etc.';\n    });\n\n    document.getElementById('btnConfirmReplace').addEventListener('click', () => {\n      hideCollisionPrompt();\n      submitAddAccount(true);\n    });\n\n    document.getElementById('btnAdd').addEventListener('click', () => {\n      if (!state.masterKey) {\n        showToast('Unlock vault first');\n        return;\n      }\n      hideCollisionPrompt();\n      switchToAddTab('manual');\n      document.getElementById('addModal').classList.add('active');\n    });\n\n    document.getElementById('btnCancelAdd').addEventListener('click', () => {\n      hideCollisionPrompt();\n      document.getElementById('addModal').classList.remove('active');\n    });\n\n    document.getElementById('btnSubmitAdd').addEventListener('click', () => {\n      submitAddAccount(false);\n    });\n\n    async function submitAddAccount(forceReplace = false) {\n      const uriInput = document.getElementById('addUriInput').value.trim();\n      let service = document.getElementById('addServiceInput').value.trim();\n      let label = document.getElementById('addLabelInput').value.trim();\n      let secret = uriInput;\n\n      if (uriInput.startsWith('otpauth://')) {\n        try {\n          const url = new URL(uriInput);\n          secret = url.searchParams.get('secret') || '';\n          service = url.searchParams.get('issuer') || '';\n          if (url.pathname) {\n            const pathPart = decodeURIComponent(url.pathname.replace(/^\\/+/, ''));\n            if (pathPart.includes(':')) {\n              const parts = pathPart.split(':');\n              if (!service) service = parts[0].trim();\n              label = parts.slice(1).join(':').trim();\n            } else if (!service) {\n              if (pathPart.includes('@')) {\n                const atParts = pathPart.split('@');\n                label = atParts[0].trim();\n                service = atParts[1].trim();\n              } else {\n                service = pathPart.trim();\n              }\n            } else {\n              label = pathPart.trim();\n            }\n          }\n        } catch (_) {}\n      }\n\n      if (!secret || !service) {\n        showToast('Provide service & key');\n        return;\n      }\n\n      if (!forceReplace) {\n        const normService = service.toLowerCase();\n        const normLabel = (label || '').toLowerCase();\n        const existing = state.decryptedAccounts.find(a =>\n          a.serviceName.toLowerCase() === normService &&\n          (a.accountLabel || '').toLowerCase() === normLabel\n        );\n\n        if (existing) {\n          const prompt = document.getElementById('addCollisionPrompt');\n          const msg = document.getElementById('collisionMsgText');\n          const nameText = label ? `${service} (${label})` : service;\n          msg.textContent = `\"${nameText}\" is already in your vault. Do you want to replace its 2FA key, or add a label to keep both?`;\n          prompt.style.display = 'block';\n          document.getElementById('addFormActions').style.display = 'none';\n          return;\n        }\n      }\n\n      const { ciphertext, iv } = await encryptSecret(secret, state.masterKey);\n      const initData = tg?.initData || '';\n\n      const res = await fetch('/api/miniapp/add', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          initData,\n          serviceName: service,\n          accountLabel: label,\n          ciphertext: Array.from(ciphertext),\n          iv: Array.from(iv),\n        }),\n      });\n\n      if (res.ok) {\n        const resData = await res.json().catch(() => ({}));\n        showToast(resData.action === 'updated' || forceReplace ? 'Account Updated' : 'Account Saved');\n        document.getElementById('addModal').classList.remove('active');\n        document.getElementById('addUriInput').value = '';\n        document.getElementById('addServiceInput').value = '';\n        document.getElementById('addLabelInput').value = '';\n        hideCollisionPrompt();\n        await syncVault();\n      } else {\n        showToast('Save failed');\n      }\n    }\n\n    syncVault();\n  </script>\n</body>\n</html>\n";
